//! The bytes behind `portfolio_server::assets`, embedded at compile time.
//!
//! The favicon and fonts are committed under `assets/`. The Open Graph card, the resume PDFs and
//! the app icons are generated by `portfolio-resume` and copied into `OUT_DIR` by `build.rs`,
//! which falls back to an empty file when the generator has not run. The tables of generated
//! files are derived from `portfolio_data`, so a language or an icon added there is served
//! without an edit here.

use portfolio_server::assets::{EmbeddedAssets, NamedFile};

// `RESUMES` and `APP_ICON_FILES`, written by `build.rs`.
include!(concat!(env!("OUT_DIR"), "/resumes.rs"));
include!(concat!(env!("OUT_DIR"), "/app_icons.rs"));

/// The vendored fonts. Kept in sync with `fonts.css` and `scripts/vendor-fonts.mjs`.
const FONTS: &[NamedFile] = &[
    (
        "space-grotesk-latin-400-normal.woff2",
        include_bytes!("../../assets/fonts/space-grotesk-latin-400-normal.woff2"),
    ),
    (
        "space-grotesk-latin-500-normal.woff2",
        include_bytes!("../../assets/fonts/space-grotesk-latin-500-normal.woff2"),
    ),
    (
        "space-grotesk-latin-600-normal.woff2",
        include_bytes!("../../assets/fonts/space-grotesk-latin-600-normal.woff2"),
    ),
    (
        "space-grotesk-latin-700-normal.woff2",
        include_bytes!("../../assets/fonts/space-grotesk-latin-700-normal.woff2"),
    ),
    (
        "jetbrains-mono-latin-400-normal.woff2",
        include_bytes!("../../assets/fonts/jetbrains-mono-latin-400-normal.woff2"),
    ),
    (
        "jetbrains-mono-latin-500-normal.woff2",
        include_bytes!("../../assets/fonts/jetbrains-mono-latin-500-normal.woff2"),
    ),
    (
        "jetbrains-mono-latin-700-normal.woff2",
        include_bytes!("../../assets/fonts/jetbrains-mono-latin-700-normal.woff2"),
    ),
];

/// Every file the asset router serves.
pub(super) const EMBEDDED: EmbeddedAssets = EmbeddedAssets {
    favicon: include_bytes!("../../assets/favicon.svg"),
    og_image: include_bytes!(concat!(env!("OUT_DIR"), "/og-image.png")),
    fonts: FONTS,
    resumes: &RESUMES,
    app_icons: &APP_ICON_FILES,
};
